void testRasterOverlayRectangleCompositionUsesProjectedWebMercatorHeight() {
    auto imageryScheme = TileScheme::createXYZWebMercator();
    const TileKey sourceKey{"XYZ-WebMercator", 2, 1, 0};
    const Rectangle sourceBounds = imageryScheme->tileToRectangle(sourceKey);
    const double midLatitude =
        (sourceBounds.south() + sourceBounds.north()) * 0.5;
    const Rectangle targetBounds(
        sourceBounds.west(),
        midLatitude,
        sourceBounds.east(),
        sourceBounds.north());

    std::vector<RasterOverlayTileProvider::RectangleSourceImage> sources;
    sources.push_back(RasterOverlayTileProvider::RectangleSourceImage{
        sourceKey,
        sourceBounds,
        makeDecodedRgbaImage(64, 64)});

    std::unique_ptr<DecodedImage> composed =
        RasterOverlayTileProvider::composeRectangleImages(
            *imageryScheme,
            targetBounds,
            sourceKey.z,
            std::move(sources),
            4096);

    const double sourceProjectedHeight =
        std::log(std::tan(sourceBounds.north() * 0.5 + M_PI * 0.25)) -
        std::log(std::tan(sourceBounds.south() * 0.5 + M_PI * 0.25));
    const double targetProjectedHeight =
        std::log(std::tan(targetBounds.north() * 0.5 + M_PI * 0.25)) -
        std::log(std::tan(targetBounds.south() * 0.5 + M_PI * 0.25));
    const int expectedHeight = static_cast<int>(
        std::ceil(targetProjectedHeight / (sourceProjectedHeight / 64.0)));

    check(composed && composed->width == 64 &&
              composed->height == expectedHeight &&
              expectedHeight != 32,
          "RasterOverlayTileProvider: WebMercator rectangle composition sizes target images in projected space like cesium-native");
}

void testRasterOverlayRectangleCompositionKeepsTinyProjectedOverlap() {
    auto imageryScheme = TileScheme::createXYZWebMercator();
    const TileKey sourceKey{"XYZ-WebMercator", 2, 1, 0};
    const Rectangle sourceBounds = imageryScheme->tileToRectangle(sourceKey);
    const double tinyHeight = sourceBounds.height() * 0.001;
    const Rectangle targetBounds(
        sourceBounds.west(),
        sourceBounds.north() - tinyHeight,
        sourceBounds.east(),
        sourceBounds.north());

    std::vector<RasterOverlayTileProvider::RectangleSourceImage> sources;
    sources.push_back(RasterOverlayTileProvider::RectangleSourceImage{
        sourceKey,
        sourceBounds,
        makeDecodedRgbaImage(64, 64)});

    std::unique_ptr<DecodedImage> composed =
        RasterOverlayTileProvider::composeRectangleImages(
            *imageryScheme,
            targetBounds,
            sourceKey.z,
            std::move(sources),
            4096);

    check(composed && composed->width == 64 && composed->height == 1,
          "RasterOverlayTileProvider: tiny target overlap still produces a one-pixel projected image like cesium-native");
}

void testRasterOverlayUploadsStopAfterElapsedBudgetExpires() {
    PendingRectangleImageryProvider imagery;
    auto imageryScheme = TileScheme::createXYZWebMercator();
    auto uploader = std::make_unique<SlowRasterTextureUploader>();
    SlowRasterTextureUploader* rawUploader = uploader.get();
    RasterOverlayTileProvider provider(
        imagery,
        *imageryScheme,
        std::move(uploader));

    TileKey firstKey{imageryScheme->id(), 1, 0, 0};
    TileKey secondKey{imageryScheme->id(), 1, 1, 0};
    RasterOverlayTileProvider::TilePtr firstTile = provider.getTile(firstKey);
    RasterOverlayTileProvider::TilePtr secondTile = provider.getTile(secondKey);

    check(firstTile && provider.loadTileThrottled(*firstTile, nullptr) &&
              secondTile && provider.loadTileThrottled(*secondTile, nullptr) &&
              imagery.pendingRequests.size() == 2,
          "RasterOverlayTileProvider: upload budget test queues two imagery requests");
    if (imagery.pendingRequests.size() < 2) {
        return;
    }

    imagery.pendingRequests[0].callback(
        firstKey,
        makeDecodedRgbaImage(4, 4));
    imagery.pendingRequests[1].callback(
        secondKey,
        makeDecodedRgbaImage(4, 4));
    check(provider.getPendingUploadCount() == 2,
          "RasterOverlayTileProvider: upload budget test has two pending uploads");

    FrameResourceBudgetConfig config;
    config.maxRasterUploadsPerFrame = 4;
    config.mainThreadTimeMs = 0.001;
    FrameResourceBudget firstFrameBudget;
    firstFrameBudget.beginFrame(1, config);
    const int firstProcessed =
        provider.processPendingUploads(false, &firstFrameBudget);
    check(firstProcessed == 1 &&
              rawUploader->uploadCount == 1 &&
              provider.getPendingUploadCount() == 1 &&
              firstFrameBudget.rasterUploadsUsed() == 1,
          "RasterOverlayTileProvider: elapsed upload cost stops later uploads in the same frame");

    FrameResourceBudget secondFrameBudget;
    secondFrameBudget.beginFrame(2, config);
    const int secondProcessed =
        provider.processPendingUploads(false, &secondFrameBudget);
    check(secondProcessed == 1 &&
              rawUploader->uploadCount == 2 &&
              provider.getPendingUploadCount() == 0,
          "RasterOverlayTileProvider: deferred upload resumes on the next frame");
}

