void testQuantizedMeshVertexUvAndHeightGolden() {
    auto scheme = TileScheme::createGeographicTMS();
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    const Rectangle bounds = scheme->tileToRectangle(rootKey);
    const float minimumHeight = -50.0f;
    const float maximumHeight = 150.0f;
    const std::vector<uint8_t> bytes = makeQuantizedMeshBytes(
        "", false, false, Vec3::zero(), minimumHeight, maximumHeight);

    std::unique_ptr<SurfaceTileMesh> mesh =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            bytes.data(),
            bytes.size(),
            bounds);

    check(mesh != nullptr && mesh->vertices.size() == 3 &&
              mesh->indices.size() == 3,
          "QuantizedMeshParser: golden triangle mesh parses with exact counts");
    if (!mesh || mesh->vertices.size() < 3) return;

    // Quantized-mesh vertex buffers are delta/zigzag encoded. The helper above
    // decodes to (u,v,h) = (0,0,0), (32767,0,0), (0,32767,0).
    // Format v=0 is the south edge, while render UV v=0 is north, so imagery
    // V is flipped.
    check(std::abs(mesh->vertices[0].uv[0] - 0.0f) < 1e-6f &&
              std::abs(mesh->vertices[0].uv[1] - 1.0f) < 1e-6f &&
              std::abs(mesh->vertices[1].uv[0] - 1.0f) < 1e-6f &&
              std::abs(mesh->vertices[1].uv[1] - 1.0f) < 1e-6f &&
              std::abs(mesh->vertices[2].uv[0] - 0.0f) < 1e-6f &&
              std::abs(mesh->vertices[2].uv[1] - 0.0f) < 1e-6f,
          "QuantizedMeshParser: quantized U/V decode and imagery V flip match format golden");

    const auto& ellipsoid = Ellipsoid::WGS84();
    const Cartographic sw =
        ellipsoid.cartesianToCartographic(mesh->vertices[0].positionEcef);
    const Cartographic se =
        ellipsoid.cartesianToCartographic(mesh->vertices[1].positionEcef);
    const Cartographic nw =
        ellipsoid.cartesianToCartographic(mesh->vertices[2].positionEcef);
    check(std::abs(sw.longitude() - bounds.west()) < 1e-8 &&
              std::abs(sw.latitude() - bounds.south()) < 1e-8 &&
              std::abs(sw.height() - minimumHeight) < 1e-3,
          "QuantizedMeshParser: vertex 0 decodes to southwest min-height corner");
    check(std::abs(se.longitude() - bounds.east()) < 1e-8 &&
              std::abs(se.latitude() - bounds.south()) < 1e-8 &&
              std::abs(se.height() - minimumHeight) < 1e-3,
          "QuantizedMeshParser: vertex 1 decodes to southeast min-height corner");
    check(std::abs(nw.longitude() - bounds.west()) < 1e-8 &&
              std::abs(nw.latitude() - bounds.north()) < 1e-8 &&
              std::abs(nw.height() - minimumHeight) < 1e-3,
          "QuantizedMeshParser: vertex 2 decodes to northwest min-height corner");
}

void testQuantizedMeshWaterMaskExtensions() {
    auto scheme = TileScheme::createGeographicTMS();
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    const Rectangle bounds = scheme->tileToRectangle(rootKey);

    const std::vector<uint8_t> allWaterBytes =
        makeQuantizedMeshBytesWithWaterMask({255});
    std::unique_ptr<SurfaceTileMesh> allWater =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            allWaterBytes.data(),
            allWaterBytes.size(),
            bounds,
            true);
    check(allWater && allWater->waterMask.allWater &&
              !allWater->waterMask.allLand &&
              allWater->waterMask.data.empty(),
          "QuantizedMeshParser: one-byte water mask marks tile all water like cesium-native");

    const std::vector<uint8_t> allLandBytes =
        makeQuantizedMeshBytesWithWaterMask({0});
    std::unique_ptr<SurfaceTileMesh> allLand =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            allLandBytes.data(),
            allLandBytes.size(),
            bounds,
            true);
    check(allLand && allLand->waterMask.allLand &&
              !allLand->waterMask.allWater &&
              allLand->waterMask.data.empty(),
          "QuantizedMeshParser: zero one-byte water mask marks tile all land like cesium-native");

    std::vector<uint8_t> mask(256 * 256, 0);
    mask[0] = 7;
    mask[12345] = 255;
    const std::vector<uint8_t> maskBytes =
        makeQuantizedMeshBytesWithWaterMask(mask);
    std::unique_ptr<SurfaceTileMesh> mixed =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            maskBytes.data(),
            maskBytes.size(),
            bounds,
            true);
    check(mixed && !mixed->waterMask.allLand &&
              !mixed->waterMask.allWater &&
              mixed->waterMask.data.size() == 256 * 256 * 4,
          "QuantizedMeshParser: 256x256 water mask becomes renderer RGBA8 data");
    check(mixed && mixed->waterMask.data[3] == 7 &&
              mixed->waterMask.data[12345 * 4 + 3] == 255 &&
              mixed->waterMask.data[12345 * 4] == 255 &&
              mixed->waterMask.data[12345 * 4 + 1] == 255 &&
              mixed->waterMask.data[12345 * 4 + 2] == 255,
          "QuantizedMeshParser: water mask alpha values preserve cesium-native 0-land 255-water semantics");

    std::vector<uint8_t> duplicateBytes =
        makeQuantizedMeshBytesWithWaterMask(mask);
    appendPod<uint8_t>(duplicateBytes, 2);
    appendPod<uint32_t>(duplicateBytes, 1);
    appendPod<uint8_t>(duplicateBytes, 255);
    std::unique_ptr<SurfaceTileMesh> duplicate =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            duplicateBytes.data(),
            duplicateBytes.size(),
            bounds,
            true);
    check(duplicate && duplicate->waterMask.allWater &&
              !duplicate->waterMask.allLand &&
              duplicate->waterMask.data.empty(),
          "QuantizedMeshParser: later one-byte water mask replaces earlier 256x256 mask like cesium-native");

    std::vector<uint8_t> invalidWaterThenMetadata = makeQuantizedMeshBytes();
    appendPod<uint8_t>(invalidWaterThenMetadata, 2);
    appendPod<uint32_t>(invalidWaterThenMetadata, 2);
    appendPod<uint8_t>(invalidWaterThenMetadata, 7);
    appendPod<uint8_t>(invalidWaterThenMetadata, 9);
    const std::string metadata = R"json({
      "available": [
        [{"startX":0,"startY":0,"endX":1,"endY":0}]
      ]
    })json";
    appendPod<uint8_t>(invalidWaterThenMetadata, 4);
    appendPod<uint32_t>(
        invalidWaterThenMetadata,
        static_cast<uint32_t>(sizeof(uint32_t) + metadata.size()));
    appendPod<uint32_t>(
        invalidWaterThenMetadata,
        static_cast<uint32_t>(metadata.size()));
    invalidWaterThenMetadata.insert(
        invalidWaterThenMetadata.end(),
        metadata.begin(),
        metadata.end());
    std::unique_ptr<SurfaceTileMesh> invalidWater =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            invalidWaterThenMetadata.data(),
            invalidWaterThenMetadata.size(),
            bounds,
            true);
    check(invalidWater &&
              invalidWater->waterMask.allLand &&
              !invalidWater->waterMask.allWater &&
              invalidWater->waterMask.data.empty() &&
              invalidWater->metadataAvailability.size() == 1 &&
              invalidWater->metadataAvailability[0] ==
                  QuantizedMeshAvailabilityRange{0, 0, 0, 1, 0},
          "QuantizedMeshParser: unsupported water mask lengths are skipped before later extensions like cesium-native");

    std::vector<uint8_t> unknownThenWaterBytes = makeQuantizedMeshBytes();
    appendPod<uint8_t>(unknownThenWaterBytes, 99);
    appendPod<uint32_t>(unknownThenWaterBytes, 3);
    appendPod<uint8_t>(unknownThenWaterBytes, 11);
    appendPod<uint8_t>(unknownThenWaterBytes, 22);
    appendPod<uint8_t>(unknownThenWaterBytes, 33);
    appendPod<uint8_t>(unknownThenWaterBytes, 2);
    appendPod<uint32_t>(unknownThenWaterBytes, 1);
    appendPod<uint8_t>(unknownThenWaterBytes, 255);
    std::unique_ptr<SurfaceTileMesh> unknownThenWater =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            unknownThenWaterBytes.data(),
            unknownThenWaterBytes.size(),
            bounds,
            true);
    check(unknownThenWater && unknownThenWater->waterMask.allWater &&
              !unknownThenWater->waterMask.allLand,
          "QuantizedMeshParser: unknown extensions are skipped before later known extensions like cesium-native");

    std::unique_ptr<SurfaceTileMesh> disabled =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            allWaterBytes.data(),
            allWaterBytes.size(),
            bounds,
            false);
    check(disabled && !disabled->waterMask.allWater &&
              disabled->waterMask.allLand &&
              disabled->waterMask.data.empty() &&
              !disabled->waterMask.valid(),
          "QuantizedMeshParser: disabled water mask ignores extension like cesium-native");

    std::vector<uint8_t> disabledWaterThenMetadata =
        makeQuantizedMeshBytesWithWaterMask({255});
    appendPod<uint8_t>(disabledWaterThenMetadata, 4);
    appendPod<uint32_t>(
        disabledWaterThenMetadata,
        static_cast<uint32_t>(sizeof(uint32_t) + metadata.size()));
    appendPod<uint32_t>(
        disabledWaterThenMetadata,
        static_cast<uint32_t>(metadata.size()));
    disabledWaterThenMetadata.insert(
        disabledWaterThenMetadata.end(),
        metadata.begin(),
        metadata.end());
    std::unique_ptr<SurfaceTileMesh> disabledWithMetadata =
        QuantizedMeshParser::parseToSurfaceTileMesh(
            disabledWaterThenMetadata.data(),
            disabledWaterThenMetadata.size(),
            bounds,
            false);
    check(disabledWithMetadata &&
              !disabledWithMetadata->waterMask.valid() &&
              disabledWithMetadata->metadataAvailability.size() == 1 &&
              disabledWithMetadata->metadataAvailability[0] ==
                  QuantizedMeshAvailabilityRange{0, 0, 0, 1, 0},
          "QuantizedMeshParser: disabled water mask still advances to later metadata like cesium-native");
}

void testQuantizedMeshProviderRasterizesCesiumHeightmapGrid() {
    QuantizedMeshTerrainProvider provider(
        "https://example.invalid/{z}/{x}/{y}.terrain");
    const float minimumHeight = -50.0f;
    const float maximumHeight = 150.0f;
    const std::vector<uint8_t> bytes = makeQuantizedMeshBytes(
        "", false, false, Vec3::zero(), minimumHeight, maximumHeight);

    std::unique_ptr<DecodedHeightmap> heightmap =
        provider.decodeTile(bytes.data(), bytes.size());

    check(heightmap != nullptr,
          "QuantizedMeshTerrainProvider: quantized mesh decodes to rasterized heightmap");
    check(heightmap && heightmap->tileSize == 65 &&
              heightmap->heights.size() == 65u * 65u,
          "QuantizedMeshTerrainProvider: rasterized heightmap uses cesium-native 65x65 grid");
    check(heightmap &&
              std::abs(heightmap->minHeight - minimumHeight) < 1e-6 &&
              std::abs(heightmap->maxHeight - maximumHeight) < 1e-6,
          "QuantizedMeshTerrainProvider: rasterized heightmap preserves quantized-mesh header height range");
    check(heightmap &&
              std::abs(heightmap->heights.front() - minimumHeight) < 1e-3f &&
              std::abs(heightmap->heights[64] - minimumHeight) < 1e-3f &&
              std::abs(heightmap->heights[64u * 65u] - minimumHeight) < 1e-3f,
          "QuantizedMeshTerrainProvider: rasterized grid decodes quantized corner heights");
    check(heightmap && heightmap->rawData == bytes,
          "QuantizedMeshTerrainProvider: decoded heightmap retains raw quantized mesh for triangulated mesh reconstruction");
}

void testTilesetUsesQuantizedMeshRtcOrigin() {
    auto provider = std::make_unique<QuantizedMeshTerrainProvider>(
        "https://example.invalid/fallback/{z}/{x}/{y}.terrain");
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset(std::move(provider), std::move(scheme), {}, nullptr, TilesetOptions{});

    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    const Vec3 boundingSphereCenter(3456.0, -7890.0, 12345.0);
    const Vec3 tileCenter(-3456.0, 7890.0, -12345.0);
    auto heightmap = makeFlatHeightmap(0.0f);
    heightmap->rawData = makeQuantizedMeshBytes(
        "", false, false, boundingSphereCenter, 0.0f, 100.0f, tileCenter);
    TilesetTestAccess::putTerrainCache(tileset, rootKey, std::move(heightmap));

    check(root != nullptr,
          "Tileset: RTC-origin root tile is created");
    if (!root) return;

    TilesetTestAccess::ensureTileMesh(tileset, *root);
    const Vec3 originDelta =
        TilesetTestAccess::localOrigin(*root) - boundingSphereCenter;
    check(originDelta.length() < 1e-12,
          "Tileset: quantized-mesh BoundingSphereCenter wins over centroid RTC origin");
}

void testTileResourceDirtyInvalidatesRevisionAndCacheOnly() {
    auto provider = std::make_unique<QuantizedMeshTerrainProvider>(
        "https://example.invalid/{z}/{x}/{y}.terrain");
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset(std::move(provider), std::move(scheme), {}, nullptr, TilesetOptions{});

    TilesetTestAccess::primeCleanReusableResources(tileset);
    const uint64_t beforeRevision = TilesetTestAccess::resourceRevision(tileset);

    TilesetTestAccess::markTileResourcesDirty(tileset);

    check(TilesetTestAccess::resourceRevision(tileset) == beforeRevision + 1,
          "Tileset: resource dirty bumps resource revision");
    check(TilesetTestAccess::cacheBytesDirty(tileset),
          "Tileset: resource dirty marks cache bytes dirty");
    check(TilesetTestAccess::selectionReuseReusable(tileset),
          "Tileset: resource dirty preserves selection reuse for static loading");
}

