void testTileLoadSchedulerSortsAndQueuesUpsampledTerrain() {
    TileLoadLifecycle lifecycle;
    FrameResourceBudgetConfig config;
    config.maxNetworkRequestsPerFrame = 4;
    config.maxNetworkInflight = 4;
    FrameResourceBudget budget;
    budget.beginFrame(1, config);

    const TileKey normalKey{"test", 1, 0, 0};
    const TileKey urgentKey{"test", 1, 1, 0};
    TilesetTile normalTile(normalKey, Rectangle{});
    TilesetTile urgentTile(urgentKey, Rectangle{});
    normalTile.content.upsampledFromParent = true;
    urgentTile.content.upsampledFromParent = true;
    std::vector<int> prepareOrder;
    std::vector<int> markedOrder;

    TileLoadRequestOutcome outcome =
        TileLoadScheduler::requestMissingTiles(
            {
                TileLoadRequest{
                    normalKey,
                    TileLoadPriorityGroup::Normal,
                    0.0},
                TileLoadRequest{
                    urgentKey,
                    TileLoadPriorityGroup::Urgent,
                    100.0},
            },
            TileLoadSchedulerInput{
                lifecycle,
                budget,
                nullptr,
                nullptr},
            testCacheKeyForTile,
            [&urgentKey,
             &normalTile,
             &urgentTile](const TileKey& key,
                          const std::string&,
                          TilesetTile*& tileState) {
                tileState = key == urgentKey ? &urgentTile : &normalTile;
                TileLoadRequestSnapshot snapshot;
                snapshot.hasTile = true;
                snapshot.upsampledFromParent = true;
                return snapshot;
            },
            [](const std::string&) { return false; },
            [&prepareOrder](TilesetTile& tile, double) {
                prepareOrder.push_back(tile.key.x);
                return true;
            },
            [&markedOrder](const TileKey& key) {
                markedOrder.push_back(key.x);
            });

    check(outcome.issued == 2 && !outcome.blockedByInflight,
          "TileLoadScheduler: upsampled requests are issued");
    check(prepareOrder.size() == 2 &&
              prepareOrder[0] == urgentKey.x &&
              prepareOrder[1] == normalKey.x,
          "TileLoadScheduler: scheduler applies shared priority ordering");
    check(markedOrder == prepareOrder,
          "TileLoadScheduler: issued upsampled requests mark loading in order");
    check(lifecycle.counts().terrainUploads == 2,
          "TileLoadScheduler: upsampled requests enter pending upload queue");
}

void testTileLoadSchedulerContinuesAfterUpsampleSourceWait() {
    class DeferredTerrainProvider final : public TerrainProvider {
    public:
        std::string id() const override {
            return "scheduler-continue-after-upsample-wait";
        }
        std::string schemeId() const override { return "test"; }
        int minZoom() const override { return 0; }
        int maxZoom() const override { return 2; }
        int tileSize() const override { return 2; }
        std::string buildUrl(const TileKey&) const override {
            return "memory://scheduler-continue-after-upsample-wait";
        }
        void requestTile(const TileKey&,
                         CancellationToken,
                         HeightmapCallback,
                         HttpRequestPriority = HttpRequestPriority::Normal) override {
            ++requestCount;
        }
        std::unique_ptr<DecodedHeightmap> decodeTile(
            const uint8_t*,
            size_t) override {
            return nullptr;
        }
        int requestCount = 0;
    };

    TileLoadLifecycle lifecycle;
    FrameResourceBudgetConfig config;
    config.maxNetworkRequestsPerFrame = 4;
    config.maxNetworkInflight = 4;
    FrameResourceBudget budget;
    budget.beginFrame(1, config);

    const TileKey waitingUpsampleKey{"test", 2, 0, 0};
    const TileKey loadableTerrainKey{"test", 1, 1, 0};
    TilesetTile waitingTile(waitingUpsampleKey, Rectangle{});
    waitingTile.content.upsampledFromParent = true;
    DeferredTerrainProvider provider;
    std::vector<int> plannedLevels;
    std::vector<int> preparedLevels;
    std::vector<int> markedLevels;

    TileLoadRequestOutcome outcome =
        TileLoadScheduler::requestMissingTiles(
            {
                TileLoadRequest{
                    loadableTerrainKey,
                    TileLoadPriorityGroup::Normal,
                    50.0},
                TileLoadRequest{
                    waitingUpsampleKey,
                    TileLoadPriorityGroup::Urgent,
                    100.0},
            },
            TileLoadSchedulerInput{
                lifecycle,
                budget,
                &provider,
                nullptr},
            testCacheKeyForTile,
            [&waitingUpsampleKey,
             &waitingTile,
             &plannedLevels](const TileKey& key,
                              const std::string&,
                              TilesetTile*& tileState) {
                plannedLevels.push_back(key.z);
                TileLoadRequestSnapshot snapshot;
                if (key == waitingUpsampleKey) {
                    tileState = &waitingTile;
                    snapshot.hasTile = true;
                    snapshot.upsampledFromParent = true;
                } else {
                    tileState = nullptr;
                    snapshot.terrainProviderSupportsTile = true;
                }
                return snapshot;
            },
            [](const std::string&) { return false; },
            [&preparedLevels](TilesetTile& tile, double) {
                preparedLevels.push_back(tile.key.z);
                return false;
            },
            [&markedLevels](const TileKey& key) {
                markedLevels.push_back(key.z);
            });

    check(outcome.issued == 1 && !outcome.blockedByInflight,
          "TileLoadScheduler: waiting upsample source does not block later request");
    check(plannedLevels.size() == 2 &&
              plannedLevels[0] == waitingUpsampleKey.z &&
              plannedLevels[1] == loadableTerrainKey.z &&
              preparedLevels.size() == 1 &&
              preparedLevels.front() == waitingUpsampleKey.z,
          "TileLoadScheduler: upsample wait is local to that request");
    check(provider.requestCount == 1 &&
              markedLevels.size() == 1 &&
              markedLevels.front() == loadableTerrainKey.z &&
              lifecycle.pendingRequestCount() == 1 &&
              lifecycle.counts().terrainUploads == 0,
          "TileLoadScheduler: later terrain request still issues without local upsample upload");
}

void testTileLoadSchedulerContinuesAfterMissingUpsampleTileState() {
    TileLoadLifecycle lifecycle;
    FrameResourceBudgetConfig config;
    config.maxNetworkRequestsPerFrame = 4;
    config.maxNetworkInflight = 4;
    FrameResourceBudget budget;
    budget.beginFrame(1, config);

    const TileKey missingTileStateKey{"test", 2, 0, 0};
    const TileKey readyUpsampleKey{"test", 2, 1, 0};
    TilesetTile readyTile(readyUpsampleKey, Rectangle{});
    readyTile.content.upsampledFromParent = true;
    std::vector<int> plannedColumns;
    std::vector<int> preparedColumns;
    std::vector<int> markedColumns;

    TileLoadRequestOutcome outcome =
        TileLoadScheduler::requestMissingTiles(
            {
                TileLoadRequest{
                    readyUpsampleKey,
                    TileLoadPriorityGroup::Normal,
                    50.0},
                TileLoadRequest{
                    missingTileStateKey,
                    TileLoadPriorityGroup::Urgent,
                    100.0},
            },
            TileLoadSchedulerInput{
                lifecycle,
                budget,
                nullptr,
                nullptr},
            testCacheKeyForTile,
            [&missingTileStateKey,
             &readyTile,
             &plannedColumns](const TileKey& key,
                               const std::string&,
                               TilesetTile*& tileState) {
                plannedColumns.push_back(key.x);
                TileLoadRequestSnapshot snapshot;
                snapshot.hasTile = true;
                snapshot.upsampledFromParent = true;
                tileState = key == missingTileStateKey ? nullptr : &readyTile;
                return snapshot;
            },
            [](const std::string&) { return false; },
            [&preparedColumns](TilesetTile& tile, double) {
                preparedColumns.push_back(tile.key.x);
                return true;
            },
            [&markedColumns](const TileKey& key) {
                markedColumns.push_back(key.x);
            });

    check(outcome.issued == 1 && !outcome.blockedByInflight,
          "TileLoadScheduler: missing upsample tile state does not block later request");
    check(plannedColumns.size() == 2 &&
              plannedColumns[0] == missingTileStateKey.x &&
              plannedColumns[1] == readyUpsampleKey.x &&
              preparedColumns.size() == 1 &&
              preparedColumns.front() == readyUpsampleKey.x,
          "TileLoadScheduler: missing upsample tile state skips source preparation");
    check(markedColumns.size() == 1 &&
              markedColumns.front() == readyUpsampleKey.x &&
              lifecycle.counts().terrainUploads == 1,
          "TileLoadScheduler: later upsampled tile still enters local upload queue");
}

